function buildDocument(id: PolicyId, entry: Entry, lang: Language): PolicyDocument {
  const sections: PolicySection[] = [...entry.sections, ...common[lang]].map(([title, text], index) => ({
    id: `section-${index + 1}`,
    title,
    paragraphs: [text],
  }));
  return { id, title: entry.title, summary: entry.summary, sections, sources: entry.sources.map(source => policySources[source]) };
}

function buildLanguage(entries: Record<PolicyId, Entry>, lang: Language): Record<PolicyId, PolicyDocument> {
  return Object.fromEntries(policyIds.map(id => [id, buildDocument(id, entries[id], lang)])) as Record<PolicyId, PolicyDocument>;
}

export const policyContent: PolicyContent = {
  uz: buildLanguage(uz, 'uz'),
  en: buildLanguage(en, 'en'),
  ru: buildLanguage(ru, 'ru'),
};
